use serde::Serialize;
use std::path::{Path, PathBuf};
use std::process::Command;

const CLONES_DIR: &str = ".local/share/blue-clones";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Mode {
    Env,
    Bwrap,
}

impl Mode {
    pub fn parse(s: &str) -> Mode {
        match s {
            "bwrap" => Mode::Bwrap,
            _ => Mode::Env,
        }
    }
    pub fn as_str(self) -> &'static str {
        match self {
            Mode::Env => "env",
            Mode::Bwrap => "bwrap",
        }
    }
}

/// Clone ids are UUIDs generated by the shell; reject anything that could escape the clones dir.
pub fn sanitize_id(id: &str) -> Result<String, String> {
    let ok = !id.is_empty()
        && id.len() <= 64
        && id.chars().all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_');
    if ok {
        Ok(id.to_string())
    } else {
        Err(format!("invalid clone id: {id:?}"))
    }
}

pub fn clone_root(real_home: &Path, id: &str) -> PathBuf {
    real_home.join(CLONES_DIR).join(id)
}

/// The directory that becomes the app's `$HOME`.
pub fn clone_home(real_home: &Path, id: &str) -> PathBuf {
    clone_root(real_home, id).join("home")
}

/// POSIX single-quote escaping.
pub fn sh_quote(s: &str) -> String {
    format!("'{}'", s.replace('\'', "'\\''"))
}

/// Environment overrides for `env` mode.
pub fn profile_env(real_home: &Path, id: &str, has_xauthority: bool) -> Vec<(String, String)> {
    let home = clone_home(real_home, id);
    let p = |rel: &str| home.join(rel).to_string_lossy().into_owned();
    let mut v = vec![
        ("HOME".to_string(), home.to_string_lossy().into_owned()),
        ("XDG_CONFIG_HOME".to_string(), p(".config")),
        ("XDG_DATA_HOME".to_string(), p(".local/share")),
        ("XDG_CACHE_HOME".to_string(), p(".cache")),
        ("XDG_STATE_HOME".to_string(), p(".local/state")),
        // The user's Flatpak installation lives in the *real* XDG_DATA_HOME.
        (
            "FLATPAK_USER_DIR".to_string(),
            real_home.join(".local/share/flatpak").to_string_lossy().into_owned(),
        ),
    ];
    if has_xauthority {
        v.push((
            "XAUTHORITY".to_string(),
            real_home.join(".Xauthority").to_string_lossy().into_owned(),
        ));
    }
    v
}

/// Arguments for `bwrap` (everything before the program to run).
pub fn bwrap_args(real_home: &Path, id: &str) -> Vec<String> {
    let rh = real_home.to_string_lossy().into_owned();
    let ch = clone_home(real_home, id).to_string_lossy().into_owned();
    let mut a: Vec<String> = vec![
        "--dev-bind".into(), "/".into(), "/".into(),
        // the clone's private home hides the real one
        "--bind".into(), ch, rh.clone(),
    ];
    // Things the app still needs from the real profile (read-only, only if present).
    for rel in [".local/share/flatpak", ".Xauthority", ".local/share/fonts", ".config/fontconfig"] {
        let path = real_home.join(rel).to_string_lossy().into_owned();
        a.extend(["--ro-bind-try".into(), path.clone(), path]);
    }
    a.push("--die-with-parent".into());
    a
}

/// Builds the full `sh` command line that launches `exec` isolated.
/// `bwrap_available` decides whether `Mode::Bwrap` can be honoured; returns the effective mode.
pub fn build_command_line(
    exec: &str,
    mode: Mode,
    real_home: &Path,
    id: &str,
    bwrap_available: bool,
    has_xauthority: bool,
) -> (String, Mode) {
    let effective = if mode == Mode::Bwrap && !bwrap_available { Mode::Env } else { mode };
    let inner = format!("sh -c {}", sh_quote(exec));
    let line = match effective {
        Mode::Env => {
            let envs: Vec<String> = profile_env(real_home, id, has_xauthority)
                .into_iter()
                .map(|(k, v)| format!("{k}={}", sh_quote(&v)))
                .collect();
            format!("env {} {}", envs.join(" "), inner)
        }
        Mode::Bwrap => {
            let args: Vec<String> = bwrap_args(real_home, id).iter().map(|s| sh_quote(s)).collect();
            format!("bwrap {} {}", args.join(" "), inner)
        }
    };
    (line, effective)
}

fn real_home() -> Result<PathBuf, String> {
    dirs::home_dir().ok_or_else(|| "cannot determine home directory".to_string())
}

fn bwrap_installed() -> bool {
    Command::new("sh")
        .arg("-c")
        .arg("command -v bwrap >/dev/null 2>&1")
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

#[derive(Serialize)]
pub struct IsolationStatus {
    pub bwrap_available: bool,
    pub root: String,
}

#[tauri::command(async)]
pub fn clone_isolation_status() -> Result<IsolationStatus, String> {
    let home = real_home()?;
    Ok(IsolationStatus {
        bwrap_available: bwrap_installed(),
        root: home.join(CLONES_DIR).to_string_lossy().into_owned(),
    })
}

/// Launches `command` with the clone's private profile. Returns the mode that was actually used
/// (`bwrap` silently degrades to `env` when bubblewrap is missing).
#[tauri::command(async)]
pub fn launch_clone_process(
    command: String,
    clone_id: String,
    mode: String,
    app_id: Option<String>,
) -> Result<String, String> {
    let id = sanitize_id(&clone_id)?;
    let home = real_home()?;
    let profile = clone_home(&home, &id);
    for sub in [".config", ".local/share", ".local/state", ".cache"] {
        std::fs::create_dir_all(profile.join(sub)).map_err(|e| format!("create profile dir: {e}"))?;
    }
    let (line, effective) = build_command_line(
        &command,
        Mode::parse(&mode),
        &home,
        &id,
        bwrap_installed(),
        home.join(".Xauthority").exists(),
    );
    crate::commands::session::launch_process(line, app_id);
    Ok(effective.as_str().to_string())
}

/// Deletes the clone's private data (called when the clone is removed and the user chose to wipe it).
#[tauri::command(async)]
pub fn clone_profile_delete(clone_id: String) -> Result<(), String> {
    let id = sanitize_id(&clone_id)?;
    let root = clone_root(&real_home()?, &id);
    if root.exists() {
        std::fs::remove_dir_all(&root).map_err(|e| e.to_string())?;
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rejects_path_traversal_ids() {
        assert!(sanitize_id("../etc").is_err());
        assert!(sanitize_id("a/b").is_err());
        assert!(sanitize_id("").is_err());
        assert!(sanitize_id("3f2b9c1e-7a44-4d0e-9a55-aa11bb22cc33").is_ok());
    }

    #[test]
    fn env_mode_redirects_home_and_xdg() {
        let (line, mode) = build_command_line("firefox --new-instance", Mode::Env, Path::new("/home/u"), "abc", false, true);
        assert_eq!(mode, Mode::Env);
        assert!(line.starts_with("env "));
        assert!(line.contains("HOME='/home/u/.local/share/blue-clones/abc/home'"));
        assert!(line.contains("XDG_CONFIG_HOME='/home/u/.local/share/blue-clones/abc/home/.config'"));
        assert!(line.contains("XDG_DATA_HOME='/home/u/.local/share/blue-clones/abc/home/.local/share'"));
        assert!(line.contains("FLATPAK_USER_DIR='/home/u/.local/share/flatpak'"));
        assert!(line.contains("XAUTHORITY='/home/u/.Xauthority'"));
        assert!(line.ends_with("sh -c 'firefox --new-instance'"));
    }

    #[test]
    fn bwrap_binds_clone_home_over_real_home() {
        let (line, mode) = build_command_line("app", Mode::Bwrap, Path::new("/home/u"), "abc", true, false);
        assert_eq!(mode, Mode::Bwrap);
        assert!(line.starts_with("bwrap "));
        assert!(line.contains("'--bind' '/home/u/.local/share/blue-clones/abc/home' '/home/u'"));
        assert!(line.contains("'--ro-bind-try' '/home/u/.local/share/flatpak'"));
    }

    #[test]
    fn bwrap_falls_back_to_env_when_missing() {
        let (line, mode) = build_command_line("app", Mode::Bwrap, Path::new("/home/u"), "abc", false, false);
        assert_eq!(mode, Mode::Env);
        assert!(line.starts_with("env "));
    }

    #[test]
    fn quotes_single_quotes_in_exec() {
        assert_eq!(sh_quote("it's"), "'it'\\''s'");
    }
}
